"""Paper tables/figures for all fast and external conditions, no outcome selection."""
from common4 import *
from figure_style import journal_layout
from make_article import table,G,F,A
import numpy as np,pandas as pd,matplotlib.pyplot as plt,sqlite3,io

def main():
    fast=pd.read_csv(ROOT/'results/fast_centers/fast_summary.csv');fc=pd.read_csv(ROOT/'results/fast_centers/fast_cases.csv');ext=pd.read_csv(ROOT/'results/external_solar/external_cases.csv');es=pd.read_csv(ROOT/'results/external_solar/external_summary.csv');ledger=pd.read_csv(ROOT/'results/external_solar/window_ledger.csv');timing=json.loads((ROOT/'results/fast_timing/timing_gate.json').read_text());rows=[]
    primary=fast[fast.budget.eq(8)&fast.policy.eq('uniform')&fast.epsilon_Wh.eq(0)&fast.halfwidth_s.eq(.5)&fast.risk_factor.eq(1)]
    for name in ['HGB','Linear','PCHIP']:
        z=primary[primary.prior.eq(name)].iloc[0];rows.append([name,f'{z.midpoint_RMSE_Wh:.3f}',f'{z.QP_RMSE_Wh:.3f}',f'{z.continuous_RMSE_Wh:.3f}',f'{z.slope_repair_RMSE_Wh:.2g}',f'{z.radius_Wh:.3f}'])
    table('fast_main.tex','Development primary setting: B8 uniform, clean values, $h=0.5$ s and $k=1$, all 440 records. Errors use continuous RMSE in Wh with equal-source/platform weighting. Both QP and clipping preserve the same radius. Clipping uses the midpoint origin and an exact crossing basis; the earlier QP uses its frozen polyline basis.',['Prior','Midpoint','QP','Clip','Repair','$R$'],rows,label='tab:fastmain')
    rows=[]
    for key,z in fast.groupby(['policy','budget','epsilon_Wh','halfwidth_s','risk_factor'],sort=True):
        policy,budget,eps,h,k=key;z=z.set_index('prior');a=z.loc['PCHIP'];rows.append([('Uniform' if policy=='uniform' else 'Guard'),budget,f'{eps:g}',f'{h:g}',int(k),f'{a.midpoint_RMSE_Wh:.3f}',*[f'{z.loc[name,"continuous_RMSE_Wh"]:.3f}' for name in ['HGB','Linear','PCHIP']],f'{a.QP_RMSE_Wh:.3f}'])
    table('full_fast.tex','All fixed-origin clipping conditions on the original 440 development records. Errors are continuous RMSE in Wh; final column is the unchanged PCHIP QP. No setting or source is removed. Required slope repairs are available for all priors in the case CSV.',['Policy','$B$','$\\epsilon$','$h$','$k$','Mid','HGB','Linear','PCHIP','QP'],rows,long=True)
    p=ext[ext.cap_W.eq(500)&ext.budget.eq(8)&ext.epsilon_Wh.eq(0)&ext.halfwidth_s.eq(.5)&ext.risk_factor.eq(1)];summary=p.groupby('prior').mean(numeric_only=True);rows=[]
    for name in ['Linear','PCHIP']:
        z=summary.loc[name];rows.append([name,len(p[p.prior.eq(name)]),f'{z.raw_RMSE_Wh:.3f}',f'{z.midpoint_RMSE_Wh:.3f}',f'{z.QP_RMSE_Wh:.3f}',f'{z.continuous_RMSE_Wh:.3f}',f'{z.radius_Wh:.3f}'])
    table('external_primary.tex','Frozen external primary test: the same 161 eligible windows of one AtlantikSolar flight, 500 W cap, B8 uniform, clean values, $h=0.5$ s and $k=1$. All errors and radii are in Wh. Means weight windows equally and are descriptive; windows are not independent flights.',['Prior','Windows','Raw','Midpoint','QP','Clip','$R$'],rows,label='tab:externalprimary')
    rows=[];pp=p[p.prior.eq('PCHIP')].copy();pp['elapsed_block']=np.minimum(((pp.left_s-2449)//86400).astype(int),3)
    for block,z in pp.groupby('elapsed_block'):
        m=z.midpoint_RMSE_Wh.mean();error=z.continuous_RMSE_Wh.mean();rows.append([f'{24*block}--{24*(block+1)}' if block<3 else '72--81.4',len(z),f'{m:.3f}',f'{error:.3f}',f'{100*(m-error)/m:.1f}'])
    table('external_blocks.tex','Descriptive elapsed-flight blocks of the same external campaign, primary PCHIP setting. The first three blocks span 24 hours each; the final block is shorter. No independent-flight uncertainty interval is inferred.',['Elapsed hours','Windows','Midpoint, Wh','Clip, Wh','Reduction \\%'],rows,label='tab:externalblocks')
    rows=[]
    for key,z in es.groupby(['cap_W','budget','epsilon_Wh','halfwidth_s','risk_factor'],sort=True):
        cap,budget,eps,h,k=key;z=z.set_index('prior');a=z.loc['PCHIP'];rows.append([f'{cap:g}',budget,f'{eps:g}',f'{h:g}',int(k),f'{100*a.reference_in_class:.1f}',f'{a.midpoint_RMSE_Wh:.3f}',f'{z.loc["Linear","continuous_RMSE_Wh"]:.3f}',f'{a.continuous_RMSE_Wh:.3f}',f'{a.radius_Wh:.3f}'])
    table('full_external.tex','Every external sensitivity setting, all 161 eligible windows. Errors/radii are in Wh. Class column gives the percentage of native reference polylines inside the supplied cap. When this is below 100\\%, the error summary remains descriptive and the cap-based truth guarantee is not asserted for misspecified windows.',['Cap','$B$','$\\epsilon$','$h$','$k$','Class \\%','Mid','Linear','PCHIP','$R$'],rows,long=True)
    rows=[]
    for z in pp.sort_values('window_id').itertuples():rows.append([z.window_id,f'{(z.left_s-2449)/3600:.2f}',f'{z.midpoint_RMSE_Wh:.3f}',f'{z.continuous_RMSE_Wh:.3f}',f'{z.raw_RMSE_Wh:.3f}',f'{z.radius_Wh:.3f}'])
    table('external_window_results.tex','All eligible external primary PCHIP windows in chronological order. Start is elapsed flight time in hours; errors/radii are in Wh. Missing IDs remain in the screening ledger as support-gap windows and are listed explicitly in the text. No error-based exclusion is made.',['ID','Start, h','Midpoint','Clip','Raw','$R$'],rows,long=True)
    z=summary.loc['PCHIP'];improvement=100*(z.midpoint_RMSE_Wh-z.continuous_RMSE_Wh)/z.midpoint_RMSE_Wh;dev=primary[primary.prior.eq('PCHIP')].iloc[0];fg=json.loads((ROOT/'results/fast_centers/fast_gate.json').read_text());eg=json.loads((ROOT/'results/external_solar/external_gate.json').read_text());ad=json.loads((ROOT/'data/external_solar/adapter_gate.json').read_text());gaps=[{key:(None if pd.isna(value) else value) for key,value in row.items()} for row in ledger[~ledger.status.eq('ELIGIBLE')].to_dict('records')]
    report=dict(development_PCHIP_RMSE_Wh=float(dev.continuous_RMSE_Wh),development_midpoint_RMSE_Wh=float(dev.midpoint_RMSE_Wh),external_PCHIP_RMSE_Wh=float(z.continuous_RMSE_Wh),external_midpoint_RMSE_Wh=float(z.midpoint_RMSE_Wh),external_reduction_percent=float(improvement),external_radius_Wh=float(z.radius_Wh),external_raw_RMSE_Wh=float(z.raw_RMSE_Wh),external_primary_QP_optimized=int(p.QP_optimized.sum()),external_primary_QP_rows=len(p),all_external_primary_references_in_class=bool(p.reference_in_class.all()),excluded_windows=gaps,matched_timing=timing,fast_gate=fg,external_gate=eg,adapter=ad,max_1Hz_reference_RMSE_Wh=float(p.resample_1Hz_RMSE_Wh.max()),max_1Hz_reference_peak_Wh=float(p.resample_1Hz_peak_Wh.max()),oneHz_native_recovery_mean_Wh=float(pp.oneHz_recovery_native_RMSE_Wh.mean()),external_win_fraction=float((pp.continuous_RMSE_Wh<pp.midpoint_RMSE_Wh).mean()));write(A/'fast_external_numbers.json',report)
    interpretation=(f'All {fg["evaluations"]:,} development reconstructions return a checked clipped center, with maximum primal and risk residuals {fg["max_primal_residual_Wh"]:.2g} and {fg["max_risk_residual_Wh"]:.2g} Wh. The earlier QP retains its {fg["QP_fallbacks_in_original"]} midpoint fallbacks; the new clipping construction has no optimizer fallback in these histories. In the primary setting, PCHIP clipping gives {dev.continuous_RMSE_Wh:.3f} Wh versus {dev.QP_RMSE_Wh:.3f} Wh for the frozen QP and {dev.midpoint_RMSE_Wh:.3f} Wh for the sharp midpoint. The small QP/clip difference reflects the continuous crossing representation and numerical solution, rather than a new risk allowance.\n\n')
    interpretation+=(f'The matched benchmark includes {timing["paired_repetitions"]} paired repetitions over {timing["sources"]} source histories. Median complete recovery times are {1000*timing["clip_median_s"]:.2f} ms for clipping and {1000*timing["QP_median_s"]:.2f} ms for a fresh QP. The median source-level speedup is {timing["median_source_speedup"]:.2f} times, with every selected source favoring clipping in this run (range {timing["minimum_source_speedup"]:.2f}--{timing["maximum_source_speedup"]:.2f}). Both methods pass every benchmark check. These are matched local CPU observations, not onboard deployment measurements.\n')
    (G/'fast_interpretation.tex').write_text(interpretation,encoding='utf-8')
    text=(f'On the frozen external primary setting, PCHIP clipping reduces mean continuous RMSE from {z.midpoint_RMSE_Wh:.3f} to {z.continuous_RMSE_Wh:.3f} Wh ({improvement:.1f}\\%) at the same sharp mean radius {z.radius_Wh:.3f} Wh. The unchanged QP gives {z.QP_RMSE_Wh:.3f} Wh and all {len(p)} primary QP controls meet the optimizer checks. Raw PCHIP gives {z.raw_RMSE_Wh:.3f} Wh; the risk-preserving result is therefore a trade-off against raw interpolation, not an accuracy dominance claim. The PCHIP center improves midpoint error in {100*report["external_win_fraction"]:.1f}\\% of eligible windows. Four chronological block summaries and all individual primary windows are retained.\n\n')
    text+=(f'The complete external grid retains {eg["reconstruction_cases"]:,} reconstructions with no clipping refusal. Of them, {eg["reference_cap_misspecified_cases"]} use a cap below the native reference rate; all occur in the 250 W sensitivity. The fixed 500 W primary cap contains every primary reference polyline. A successful sparse compatibility test under 250 W cannot validate a cap that misses the dense reference.\n\n')
    text+=(f'The maximum 1 Hz cumulative-reference discrepancy is {report["max_1Hz_reference_RMSE_Wh"]:.6f} Wh in continuous RMSE and {report["max_1Hz_reference_peak_Wh"]:.6f} Wh at a prefix. Primary PCHIP recovery on the 1 Hz basis has mean error {report["oneHz_native_recovery_mean_Wh"]:.3f} Wh against the native reference. This checks a deterministic numerical approximation; it does not add a sensor calibration or an independent campaign.\n')
    (G/'external_interpretation.tex').write_text(text,encoding='utf-8')
    fig,axes=plt.subplots(1,2,figsize=(10,3.6));axes[0].plot((pp.left_s-2449)/3600,pp.midpoint_RMSE_Wh,color='#777777',lw=.9,label='Sharp midpoint');axes[0].plot((pp.left_s-2449)/3600,pp.continuous_RMSE_Wh,color='#176f78',lw=.9,label='PCHIP clipped center');axes[0].set(xlabel='Elapsed flight time (h)',ylabel='Continuous window RMSE (Wh)');axes[0].legend(fontsize=8);axes[1].scatter(pp.midpoint_RMSE_Wh,pp.continuous_RMSE_Wh,s=13,color='#176f78',alpha=.7);lim=max(pp.midpoint_RMSE_Wh.max(),pp.continuous_RMSE_Wh.max())*1.05;axes[1].plot([0,lim],[0,lim],'--',color='#777777',lw=.8);axes[1].set(xlabel='Midpoint RMSE (Wh)',ylabel='Clipped-center RMSE (Wh)',xlim=(0,lim),ylim=(0,lim));journal_layout(fig);fig.tight_layout();fig.savefig(F/'external_solar_recovery.png');plt.close(fig)
    bench=pd.read_csv(ROOT/'results/fast_timing/paired_timing.csv');bt=bench.groupby(['platform','source_id'])[['clip_seconds','QP_seconds']].median();fig,ax=plt.subplots(figsize=(8,3.4));x=np.arange(len(bt));ax.plot(x,1000*bt.QP_seconds,'o',ms=3,color='#a5522a',label='Fresh QP');ax.plot(x,1000*bt.clip_seconds,'s',ms=3,color='#176f78',label='Envelope clip');ax.set(xlabel='Source history (one duration-median record per source)',ylabel='Median complete recovery time (ms)',yscale='log');ax.legend(fontsize=9);journal_layout(fig);fig.tight_layout();fig.savefig(F/'matched_runtime.png');plt.close(fig)
    print(json.dumps({key:report[key] for key in ['development_PCHIP_RMSE_Wh','external_PCHIP_RMSE_Wh','external_midpoint_RMSE_Wh','external_reduction_percent','excluded_windows','external_win_fraction']},indent=2))

if __name__=='__main__':main()
